window.docContents[148].resolve({"/Preface/#Hoare-Logic--Preface--Practicalities--Building-on-Your-Own-Copy-of-Logical-Foundations":{"contents":"This project includes a copy of the Logical Foundations files that\nchapters in this volme depends on, in their own LF/ directory, so you do\nnot need a separate Logical Foundations download to build or read this volume.\nIf you have already worked through Logical Foundations and would rather this\nvolume build on your own work, copy the whole LF/ directory from your\nLogical Foundations download over this project's LF/ directory, then\nrebuild.\n\nExercises in this volume use the same star ratings, and the same\n\"advanced\"/\"optional\" markings, described in the Logical Foundations\nPreface.\n\n","context":"Hoare Logic\u0009Preface\u0009Practicalities","header":"1.3.1. Building on Your Own Copy of Logical Foundations","id":"/Preface/#Hoare-Logic--Preface--Practicalities--Building-on-Your-Own-Copy-of-Logical-Foundations"}});